def acquired_order(task, oracle, max_queries=16):
    family = task.get("family", "software")
    if isinstance(max_queries, int) and max_queries >= 0:
        budget = max_queries
    else:
        budget = 16
    used = [0]
    def ask(candidate):
        used[0] = used[0] + 1
        return oracle.query(candidate)
    def shrink(build, count, order, bulk):
        full = list(range(count))
        if budget <= 0:
            return build(full)
        first = build(full)
        if first is None:
            return build(full)
        report = ask(first)
        if not isinstance(report, dict) or report.get("verdict") != "preserved":
            return build(full)
        keep = full
        if bulk is not None and used[0] < budget:
            trial = [i for i in keep if i not in bulk]
            if trial:
                cand = build(trial)
                if cand is not None:
                    rep = ask(cand)
                    if isinstance(rep, dict) and rep.get("verdict") == "preserved":
                        keep = trial
        changed = True
        while changed and len(keep) > 1:
            changed = False
            for atom in [a for a in order if a in keep]:
                if used[0] >= budget:
                    return build(keep)
                trial_keep = [a for a in keep if a != atom]
                cand = build(trial_keep)
                if cand is None:
                    continue
                rep = ask(cand)
                if isinstance(rep, dict) and rep.get("verdict") == "preserved":
                    keep = trial_keep
                    changed = True
        return build(keep)
    if family == "graph":
        vertices = list(task.get("vertices", []))
        edges = [list(e) for e in task.get("edges", [])]
        units = []
        for v in vertices:
            units.append(("v", v))
        for i in range(len(edges)):
            units.append(("e", i))
        degree = {}
        for v in vertices:
            degree[v] = 0
        for e in edges:
            degree[e[0]] = degree.get(e[0], 0) + 1
            degree[e[1]] = degree.get(e[1], 0) + 1
        def build_graph(keep):
            kept = set(keep)
            gone = set()
            dropped_edges = set()
            for pos in range(len(units)):
                if pos not in kept:
                    if units[pos][0] == "v":
                        gone.add(units[pos][1])
                    else:
                        dropped_edges.add(units[pos][1])
            keep_v = [v for v in vertices if v not in gone]
            if not keep_v:
                return None
            kept_v = set(keep_v)
            keep_e = [e for i, e in enumerate(edges) if i not in dropped_edges and e[0] in kept_v and e[1] in kept_v]
            return {"family": "graph", "task_id": task.get("task_id"), "vertices": keep_v, "edges": keep_e, "seed": task.get("seed")}
        v_first = [i for i in range(len(units)) if units[i][0] == "v"]
        v_first = sorted(v_first, key=lambda i: (degree.get(units[i][1], 0), i))
        e_rest = [i for i in range(len(units)) if units[i][0] != "v"]
        candidate = shrink(build_graph, len(units), v_first + e_rest, None)
        return {"candidate": candidate, "queries": used[0]}
    ops = list(task.get("ops", []))
    wid = task.get("witness", {}).get("observation")
    wpos = -1
    for i, entry in enumerate(ops):
        if entry.get("id") == wid:
            wpos = i
            break
    hero = ops[wpos].get("key") if wpos >= 0 else None
    chain = [i for i, o in enumerate(ops) if wpos >= 0 and o.get("op") == "set" and o.get("key") == hero and i < wpos]
    rest = [i for i in range(len(ops)) if i != wpos and i not in chain]
    def build_sw(keep):
        kept = [ops[i] for i in sorted(keep)]
        return {"family": "software", "task_id": task.get("task_id"), "fault": task.get("fault"), "ops": kept, "witness": task.get("witness"), "seed": task.get("seed")}
    if wpos >= 0:
        order = rest + chain + [wpos]
        bulk = set(rest)
    else:
        order = list(range(len(ops)))
        bulk = None
    candidate = shrink(build_sw, len(ops), order, bulk)
    return {"candidate": candidate, "queries": used[0]}

